<script setup>
import {ref} from 'vue'
import {characters} from '../data/characters'
import {useArcade} from '../stores/arcade'
const props=defineProps({modelValue:String,locked:{type:Boolean,default:false}}),emit=defineEmits(['update:modelValue']),s=useArcade(),pending=ref(null),busy=ref(false),error=ref('')
function choose(c){if(c.id===props.modelValue&&props.locked)return;if(!props.locked){emit('update:modelValue',c.id);return}pending.value=c;error.value=''}
async function change(){if(busy.value)return;busy.value=true;error.value='';try{await s.selectCharacter(pending.value.id);pending.value=null}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><fieldset class="character-picker"><legend>나의 파트너 선택</legend><p>{{locked?'다른 포켓몬으로 변경할 때 5,000포인트를 사용해요. 캐릭터 변경 시 새 계열의 1단계로 돌아갑니다. 레벨·보유 아이템·스킨은 보존됩니다.':'함께 모험할 친구를 골라 주세요. 첫 선택은 무료예요.'}}</p><div class="character-options"><button v-for="c in characters" :key="c.id" type="button" :class="['character-choice',{chosen:modelValue===c.id}]" :style="{'--character-color':c.color}" :disabled="busy||(locked&&modelValue!==c.id&&s.data.coins<5000)" :aria-pressed="modelValue===c.id" :aria-label="c.name+' 선택'" @click="choose(c)"><span class="choice-status">{{modelValue===c.id?'✓ 선택됨':locked?'5,000 P':'SELECT'}}</span><img :src="c.image" :alt="c.name" draggable="false"/><strong>{{c.name}}</strong><span class="character-type">{{c.type}}</span></button></div><p class="character-hint">{{locked?'보유 포인트 '+s.data.coins.toLocaleString()+' P · 퀴즈로 포인트를 모아 주세요.':'파트너 변경에는 5,000포인트가 필요합니다.'}}</p><div v-if="pending" class="partner-change-confirm" role="dialog" aria-label="파트너 변경 확인"><h3>{{pending.name}}로 변경할까요?</h3><p>5,000포인트가 차감되며 새 캐릭터는 강화 전 1단계로 시작합니다. 변경 후 잔액 {{(s.data.coins-5000).toLocaleString()}} P</p><button type="button" :disabled="busy" @click="change">{{busy?'변경 중…':'5,000 P 사용하고 변경'}}</button><button type="button" class="light" :disabled="busy" @click="pending=null">취소</button><p v-if="error" role="alert">{{error}}</p></div></fieldset></template>
